options comamid=TCP remote=WRDS;
*signon username=_prompt_;
signon username="XXX" PASSWORD="XXX";
libname rwork slibref=work server=wrds;

from crspa.dsf a
left join crspa.dSE b on a.permno=b.permno & a.date=b.date
left join crspa.STOCKNAMES c on c.permno=a.permno & NAMEDT<=a.date<=NAMEENDDT
left join ff.FACTORS_daily d on a.date=d.date
having c.shrcd in(10,11) & ret~=. & year(a.date)<=1950
order by a.permno, a.date
;quit;
proc sort nodupkey; by permno date; quit;
proc download data=CRSP;quit;
endrsubmit;
data temp.BG2019; set CRSP;run;

*Load Moody's data;
proc sort data=data.Moodys_fund_20180620(where=(PERMNO~=.)) out=a01 nodupkey; by PERMNO FYEAR; quit;

proc sql; create table a03 as 
select a.permno, a.fyear, a.de, b.date-a.rdq as ET, b.ret, b.ret-b.rf as eret, b.mktrf, count(b.ret) as c
from a02 a 
left join spd.BG2019 b on a.permno=b.permno & a.rdq-100<=b.date<=a.rdq+100
group by a.permno, a.fyear having c>150;quit;

proc reg data=a03(where=(eret~=. & (-100<=ET<=-3 | 3<=ET<=100))) noprint outest=a04;
model eret = mktrf /noint;
by permno fyear;quit;

*Merge and calculate earnings announcement return;
proc sql; create table a05 as
select a.*, abs(a.de) as ade, h.mktrf as beta,
		  (exp(sum(log(1+b.ret)))-1) as Ret, (exp(sum(log(1+b.ret-b.rf-b.mktrf*h.mktrf)))-1) as aRet 
from a02 a 
left join spd.BG2019 b on a.permno=b.permno & a.rdq-1<=b.date<=a.rdq+1
left join a04 h on a.permno=h.permno & a.fyear=h.fyear
group by a.permno, a.fyear;quit;

