/*****************************************
*Trim or winsorize macro;
*byvar = none for no byvar;
*type  = delete/winsor (delete will trim, winsor will winsorize;
*dsetin = dataset to winsorize/trim;
*dsetout = dataset to output with winsorized/trimmed values;
*byvar = subsetting variables to winsorize/trim on;

%macro winsor(dsetin=, dsetout=, byvar=none, vars=, type=winsor, pctl=);

%macro Lags(in,out,cvar,tvar,vars,lags,lead);
data &out; set &in;run;
%do i = 1 %to %sysfunc(countw(&vars));
%do j = 1 %to &lags;
	proc sql; create table &out
	as select a.* 
		%if &lead=0 %then %do;
			,b.%scan(&vars, &i, ' ') as %scan(&vars, &i, ' ')_lag&j
		%end;
		%if &lead=1 %then %do;
			,b.%scan(&vars, &i, ' ') as %scan(&vars, &i, ' ')_lead&j
		%end;
	from &out a
	left join &in b on 
	/*Only add cross sectional identifier when cvar is not equal to "none"*/
	%if &cvar~=none %then %do;
	a.&cvar=b.&cvar & 
	%end;
	%if &lead=0 %then %do;
		a.&tvar=b.&tvar+&j
	%end;
	%else %do;
		a.&tvar=b.&tvar-&j
	%end;
	;quit;
%end;%end;
%mend;

*Propensity score matched sample;
proc psmatch data=a06(where=(fyear=1932));
class treat industry;
psmodel treat = age tech cvearn beta e issue leverage INCCONF CONTCONF DELAWARE MKTSHR size dividend regulated;
match method=greedy(order=random(seed=999999)) exact=industry;
output out(obs=match)=a11 matchid=_matchid;
quit;
proc sort; by _matchid;quit;

*Create constant matched data set;
proc sql; create table a07 as
select a.*, b.treat~=. as indicator, b._matchid
from a06 a 
left join a11 b on a.permno=b.permno
having ret+de+size+beta+mtb+e_lag1+ret_sync~=. & 1930<=a.fyear<=1938
;quit;

*Jump in sales plot;
proc sql; create table t01 as
select fyear, mean(sale_nm) as sale
from a07 group by fyear;quit;

*Ball and Brown plot adjusted returns;
proc sql; create table t03 as
select a.post, a.goodnews, b.date-a.rdq as ET, mean(b.ret) as ret
from a07 a
left join spd.BG2019 b on a.permno=b.permno & a.rdq-10<b.date<=a.rdq+10
left join a04 h on a.permno=h.permno & a.fyear=h.fyear
group by post, goodnews, ET;quit;

*Industries;
proc freq data=a07; table industry / out=industry;quit;

*Descriptive stats;
%DS(data=a07,varlist=de ret treat post size beta mtb ade e_lag1 ret_sync);

*Correlation matrix;
%CorrStar(data=a07,varlist=de ret treat post size beta mtb ade e_lag1 ret_sync, pval=0.01, path="[redacted-path-4ff944099508]");

*Survivorship;
proc sql; create table t04 as
select a.fyear, sum(max(b.treat~=.,0))/sum(max(a.treat~=.,0)) as c
from a07 a
left join a07 b on a.permno=b.permno & a.fyear+1=b.fyear
group by a.fyear;quit;

*Determinant model;
data d01; set a07; if treat+age+tech+cvearn+beta+e+issue+leverage+INCCONF+CONTCONF+DELAWARE+MKTSHR+size+dividend+regulated~=.;run;

